    const key = keyFn(item);
    if (!groups[key]) groups[key] = [];
    groups[key].push(item);
    return groups;
  }, {});
}", "explanation": "reduce builds up an accumulator object; for each item, the key is computed via `keyFn`, a bucket array is created on first use, and the item is pushed into its bucket.", "concepts": ["group by", "reduce"]}

